def v421_safe_matches(feed, limit=6):
    """Devuelve una lista corta y segura para pantallas anti-agobio."""
    try:
        if isinstance(feed, dict):
            matches = feed.get("matches") or []
            if not matches and isinstance(feed.get("buckets"), dict):
                for key in ("live", "today", "upcoming"):
                    matches.extend(feed.get("buckets", {}).get(key) or [])
        else:
            matches = []
        return list(matches)[:limit]
    except Exception:
        return []

