@app.route('/cliente/experiencia')
def cliente_experiencia_v419():
    gate = require_user()
    if gate:
        return gate
    user = current_user()
    picks, saved, stats = get_user_dashboard(user['id'])
    return render_template('client/v419_client_experience_home.html', user=user, picks=picks, saved=saved, stats=stats, roi_summary=enhanced_roi_summary(user['id']), sport_status=get_sport_watchlist_status(force=False), live_snapshot=live_results_snapshot(), favorite_ids=user_favorite_ids(user['id']), next_step=client_next_step(user))

@app.route('/admin/v419-experience-os')
def admin_v419_experience_os():
    gate = require_admin()
    if gate:
        return gate
    conn = get_db(); cur = conn.cursor()
    cur.execute('SELECT id,email,plan,created_at,last_login_at FROM users ORDER BY id DESC LIMIT 8')
    users = cur.fetchall()
    cur.execute('SELECT id,title,pick,cuota,score,active FROM picks ORDER BY id DESC LIMIT 8')
    picks = cur.fetchall()
    conn.close()
    return render_template('admin/v419_admin_experience_os.html', users=users, picks=picks, stats={}, api_stats=api_usage_summary(), live_odds=live_odds_manager_status(), last_api_refresh=None, platform=platform_health_summary(), recent_alerts=[], quality=quality_control_status())


