@app.route("/api/v363/shark-memory/event", methods=["POST"])
def api_v363_shark_memory_event():
    user = current_user() or {}
    data = request.get_json(silent=True) or request.form or {}
    title = str(data.get("title") or "Interacción SHARK").strip()[:140]
    detail = str(data.get("detail") or data.get("nota") or "").strip()[:600]
    event_type = str(data.get("event_type") or data.get("type") or "client_signal").strip()[:60]
    entity_key = str(data.get("entity_key") or data.get("match_key") or "").strip()[:140]
    try: score = float(data.get("score") or 0)
    except Exception: score = 0
    try: confidence = float(data.get("confidence") or score or 0)
    except Exception: confidence = 0
    conn = get_db(); cur = conn.cursor()
    cur.execute("""
        INSERT INTO shark_memory_events(user_id,event_type,entity_key,title,detail,score,confidence,payload,created_at)
        VALUES(?,?,?,?,?,?,?,?,?)
    """, (int(safe_row_get(user, "id", 0) or 0), event_type, entity_key, title, detail, score, confidence, json.dumps(dict(data), ensure_ascii=False, default=str), madrid_iso_now()))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "version": "V363", "saved": True, "title": title})

