# ===== V364 REAL DATA CONTROL + AUTOMATION INTELLIGENCE =====
def ensure_v364_schema():
    """Tablas ligeras para control real de datos, ahorro API y automatización de picks."""
    conn = get_db(); cur = conn.cursor()
    cur.execute("""
        CREATE TABLE IF NOT EXISTS data_quality_events(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entity_type TEXT DEFAULT '',
            entity_key TEXT DEFAULT '',
            title TEXT DEFAULT '',
            quality_score REAL DEFAULT 0,
            status TEXT DEFAULT '',
            issues TEXT DEFAULT '',
            payload TEXT DEFAULT '',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS pick_automation_queue(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            match_key TEXT DEFAULT '',
            title TEXT DEFAULT '',
            league TEXT DEFAULT '',
            suggested_pick TEXT DEFAULT '',
            odds_decimal TEXT DEFAULT '',
            shark_score REAL DEFAULT 0,
            confidence REAL DEFAULT 0,
            risk_label TEXT DEFAULT '',
            status TEXT DEFAULT 'pending',
            reason TEXT DEFAULT '',
            payload TEXT DEFAULT '',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            reviewed_at TEXT DEFAULT ''
        )
    """)
    cur.execute("CREATE INDEX IF NOT EXISTS idx_v364_quality_time ON data_quality_events(created_at)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_v364_queue_status ON pick_automation_queue(status, created_at)")
    conn.commit(); conn.close()


def v364_pick_quality(row):
    title = safe_row_get(row, 'title', '') or safe_row_get(row, 'match_name', '') or 'Partido sin título'
    league = safe_row_get(row, 'league', '') or safe_row_get(row, 'competition', '')
    pick = safe_row_get(row, 'pick', '') or safe_row_get(row, 'prediction', '') or safe_row_get(row, 'market', '')
    odds = safe_row_get(row, 'odds', '') or safe_row_get(row, 'quota', '') or safe_row_get(row, 'cuota', '')
    score = safe_row_get(row, 'score', '') or safe_row_get(row, 'shark_score', '') or 0
    issues = []
    quality = 100
    if not title or title == 'Partido sin título': quality -= 25; issues.append('falta_nombre_partido')
    if not league: quality -= 12; issues.append('falta_liga')
    if not pick: quality -= 18; issues.append('falta_pick')
    try:
        odds_float = float(str(odds).replace(',', '.'))
        if odds_float <= 1.01: quality -= 18; issues.append('cuota_no_valida')
    except Exception:
        odds_float = 0
        quality -= 18; issues.append('cuota_no_numerica')
    try:
        score_float = float(str(score).replace(',', '.'))
        if score_float <= 0: quality -= 10; issues.append('sin_score_shark')
    except Exception:
        score_float = 0
        quality -= 10; issues.append('score_no_numerico')
    if quality >= 82: status = 'premium_real'
    elif quality >= 62: status = 'usable_revisar'
    else: status = 'incompleto'
    return {"title": title, "league": league, "pick": pick, "odds": odds_float, "score": score_float, "quality_score": max(0, min(100, quality)), "status": status, "issues": issues}


def build_v364_data_quality(persist=False, limit=50):
    ensure_v364_schema()
    conn = get_db(); cur = conn.cursor()
    cur.execute("SELECT * FROM picks ORDER BY created_at DESC LIMIT ?", (int(limit or 50),))
    rows = cur.fetchall()
    items = []
    for r in rows:
        q = v364_pick_quality(r)
        key = str(safe_row_get(r, 'id', '') or q['title'])
        q['entity_key'] = key
        items.append(q)
        if persist:
            cur.execute("""
                INSERT INTO data_quality_events(entity_type,entity_key,title,quality_score,status,issues,payload,created_at)
                VALUES(?,?,?,?,?,?,?,?)
            """, ('pick', key, q['title'], q['quality_score'], q['status'], ','.join(q['issues']), json.dumps(q, ensure_ascii=False), madrid_iso_now()))
    if persist: conn.commit()
    avg = round(sum(x['quality_score'] for x in items) / max(len(items), 1), 1)
    premium = sum(1 for x in items if x['status'] == 'premium_real')
    revisar = sum(1 for x in items if x['status'] == 'usable_revisar')
    incompleto = sum(1 for x in items if x['status'] == 'incompleto')
    conn.close()
    return {"ok": True, "version": "V364", "persisted": bool(persist), "total": len(items), "avg_quality": avg, "premium_real": premium, "usable_revisar": revisar, "incompleto": incompleto, "items": items[:20], "updated_at": madrid_iso_now()}


def build_v364_automation_candidates(persist=False, limit=12):
    ensure_v364_schema()
    ctx = build_v363_live_context(limit=limit, persist=False)
    candidates = []
    for s in ctx.get('snapshots', []):
        score = float(s.get('shark_score') or 0)
        odds = float(s.get('odds_decimal') or 0)
        if score < 64 or odds < 1.15:
            continue
        if score >= 78:
            action = 'ENTRAR 1X2 con stake bajo/controlado'
        elif score >= 70:
            action = 'REVISAR antes de entrar: posible value 1X2'
        else:
            action = 'ESPERAR confirmación live'
        reason = f"Score SHARK {score:.0f}/100, cuota {odds:.2f}, momentum {s.get('momentum_label','')}, riesgo {s.get('risk_label','')}"
        c = {"match_key": s.get('match_key',''), "title": s.get('title',''), "league": s.get('league',''), "suggested_pick": action, "odds_decimal": odds, "shark_score": score, "confidence": min(99, round(score * 0.92, 1)), "risk_label": s.get('risk_label',''), "reason": reason, "payload": s}
        candidates.append(c)
    conn = get_db(); cur = conn.cursor()
    if persist:
        for c in candidates:
            cur.execute("""
                INSERT INTO pick_automation_queue(match_key,title,league,suggested_pick,odds_decimal,shark_score,confidence,risk_label,status,reason,payload,created_at)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
            """, (c['match_key'], c['title'], c['league'], c['suggested_pick'], str(c['odds_decimal']), c['shark_score'], c['confidence'], c['risk_label'], 'pending', c['reason'], json.dumps(c['payload'], ensure_ascii=False), madrid_iso_now()))
        conn.commit()
    cur.execute("SELECT COUNT(*) AS n FROM pick_automation_queue WHERE status='pending'")
    pending = int((cur.fetchone() or {'n':0})['n'] or 0)
    conn.close()
    return {"ok": True, "version": "V364", "persisted": bool(persist), "generated": len(candidates), "pending_queue": pending, "candidates": candidates, "updated_at": madrid_iso_now()}


def build_v364_api_saver_dashboard():
    ensure_v364_schema()
    conn = get_db(); cur = conn.cursor()
    stats = {"ok": True, "version": "V364", "updated_at": madrid_iso_now()}
    for table in ['api_cache', 'api_usage_logs', 'match_context_snapshots', 'data_quality_events', 'pick_automation_queue']:
        try:
            cur.execute(f"SELECT COUNT(*) AS n FROM {table}")
            stats[table] = int((cur.fetchone() or {'n':0})['n'] or 0)
        except Exception:
            stats[table] = 0
    try:
        cur.execute("SELECT provider, COUNT(*) AS n FROM api_usage_logs GROUP BY provider ORDER BY n DESC LIMIT 8")
        stats['providers'] = [dict(r) for r in cur.fetchall()]
    except Exception:
        stats['providers'] = []
    try:
        cur.execute("SELECT title, quality_score, status, issues, created_at FROM data_quality_events ORDER BY id DESC LIMIT 8")
        stats['latest_quality_events'] = [dict(r) for r in cur.fetchall()]
    except Exception:
        stats['latest_quality_events'] = []
    try:
        cur.execute("SELECT title, suggested_pick, shark_score, confidence, risk_label, status, created_at FROM pick_automation_queue ORDER BY id DESC LIMIT 8")
        stats['latest_queue'] = [dict(r) for r in cur.fetchall()]
    except Exception:
        stats['latest_queue'] = []
    conn.close()
    return stats


