# ===== V365 PICKS FACTORY + HISTORICAL INTELLIGENCE REAL =====
def ensure_v365_schema():
    """Persistencia real para fábrica de picks, scoring histórico y auditoría de decisiones."""
    ensure_v364_schema()
    conn = get_db(); cur = conn.cursor()
    cur.execute("""
        CREATE TABLE IF NOT EXISTS shark_pick_factory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_key TEXT,
            title TEXT,
            league TEXT,
            market TEXT,
            recommended_pick TEXT,
            odds_decimal TEXT,
            shark_score REAL DEFAULT 0,
            confidence REAL DEFAULT 0,
            value_index REAL DEFAULT 0,
            risk_label TEXT,
            stake_hint TEXT,
            decision TEXT,
            reason TEXT,
            payload TEXT,
            status TEXT DEFAULT 'draft',
            created_at TEXT,
            updated_at TEXT
        )
    """)
    cur.execute("CREATE INDEX IF NOT EXISTS idx_shark_pick_factory_status ON shark_pick_factory(status)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_shark_pick_factory_created ON shark_pick_factory(created_at)")
    cur.execute("""
        CREATE TABLE IF NOT EXISTS shark_history_signals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            signal_type TEXT,
            entity_key TEXT,
            title TEXT,
            score REAL DEFAULT 0,
            trend TEXT,
            sample_size INTEGER DEFAULT 0,
            payload TEXT,
            created_at TEXT
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS shark_decision_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entity_key TEXT,
            decision TEXT,
            score REAL DEFAULT 0,
            reason TEXT,
            payload TEXT,
            created_at TEXT
        )
    """)
    conn.commit(); conn.close()


def _v365_float(v, default=0.0):
    try:
        if v is None: return float(default)
        if isinstance(v, str): v = v.replace(',', '.').strip()
        return float(v)
    except Exception:
        return float(default)


def _v365_stake_hint(score, risk_label, value_index):
    score = _v365_float(score); value_index = _v365_float(value_index)
    risk = (risk_label or '').lower()
    if score >= 84 and value_index >= 16 and 'alto' not in risk:
        return '0,20€ - 0,50€ controlado'
    if score >= 74 and value_index >= 8:
        return '0,10€ - 0,25€ inteligente'
    if score >= 66:
        return '0,10€ simbólico / esperar confirmación'
    return 'No entrar todavía'


def _v365_decision(score, risk_label, value_index):
    score = _v365_float(score); value_index = _v365_float(value_index)
    risk = (risk_label or '').lower()
    if score >= 82 and value_index >= 14 and 'alto' not in risk:
        return 'PUBLICABLE'
    if score >= 70 and value_index >= 6:
        return 'REVISAR'
    return 'ESPERAR'


def build_v365_historical_signals(persist=False, limit=80):
    ensure_v365_schema()
    conn = get_db(); cur = conn.cursor()
    signals = []
    try:
        cur.execute("SELECT league, COUNT(*) AS n, AVG(CAST(shark_score AS REAL)) AS avg_score FROM pick_automation_queue GROUP BY league ORDER BY avg_score DESC LIMIT 12")
        for r in cur.fetchall():
            n = int((r['n'] or 0)); avg = round(_v365_float(r['avg_score']), 1)
            trend = 'fuerte' if avg >= 78 else ('estable' if avg >= 66 else 'débil')
            signals.append({'signal_type':'league_form','entity_key':r['league'] or 'General','title':f"Liga {r['league'] or 'General'}",'score':avg,'trend':trend,'sample_size':n,'payload':dict(r)})
    except Exception:
        pass
    try:
        cur.execute("SELECT status, COUNT(*) AS n, AVG(quality_score) AS avg_quality FROM data_quality_events GROUP BY status ORDER BY n DESC")
        for r in cur.fetchall():
            avg = round(_v365_float(r['avg_quality']), 1); n = int(r['n'] or 0)
            signals.append({'signal_type':'data_quality','entity_key':r['status'] or 'unknown','title':f"Calidad datos: {r['status'] or 'unknown'}",'score':avg,'trend':'premium' if avg>=80 else 'vigilar','sample_size':n,'payload':dict(r)})
    except Exception:
        pass
    try:
        cur.execute("SELECT COUNT(*) AS n, AVG(shark_score) AS avg_score FROM match_context_snapshots WHERE shark_score IS NOT NULL")
        r = cur.fetchone(); n = int((r or {'n':0})['n'] or 0); avg = round(_v365_float((r or {'avg_score':0})['avg_score']), 1)
        signals.append({'signal_type':'live_context_depth','entity_key':'live_context','title':'Profundidad Match Center Live','score':avg,'trend':'suficiente' if n>=10 else 'necesita más snapshots','sample_size':n,'payload':{'snapshots':n,'avg_score':avg}})
    except Exception:
        pass
    if persist:
        for sig in signals:
            cur.execute("""INSERT INTO shark_history_signals(signal_type,entity_key,title,score,trend,sample_size,payload,created_at)
                           VALUES(?,?,?,?,?,?,?,?)""", (sig['signal_type'], sig['entity_key'], sig['title'], sig['score'], sig['trend'], sig['sample_size'], json.dumps(sig['payload'], ensure_ascii=False), madrid_iso_now()))
        conn.commit()
    conn.close()
    return {'ok': True, 'version': 'V365', 'persisted': bool(persist), 'total': len(signals), 'signals': signals, 'updated_at': madrid_iso_now()}


def build_v365_pick_factory(persist=False, limit=14):
    ensure_v365_schema()
    base = build_v364_automation_candidates(persist=False, limit=limit)
    history = build_v365_historical_signals(persist=False)
    league_boost = {}
    for s in history.get('signals', []):
        if s.get('signal_type') == 'league_form':
            league_boost[s.get('entity_key')] = _v365_float(s.get('score'))
    factory = []
    for c in base.get('candidates', []):
        score = _v365_float(c.get('shark_score'))
        odds = _v365_float(c.get('odds_decimal'), 1.0)
        league = c.get('league') or 'General'
        boost = max(0, league_boost.get(league, 65) - 65) * 0.18
        value_index = round(max(0, (score - 60) * 0.72 + (odds - 1.0) * 9 + boost), 1)
        decision = _v365_decision(score, c.get('risk_label'), value_index)
        stake = _v365_stake_hint(score, c.get('risk_label'), value_index)
        pick = c.get('suggested_pick') or 'Revisar 1X2'
        reason = f"{decision}: score {score:.0f}/100, value index {value_index:.1f}, cuota {odds:.2f}. Stake sugerido: {stake}."
        item = {'source_key': c.get('match_key') or c.get('title'), 'title': c.get('title'), 'league': league, 'market':'1X2', 'recommended_pick': pick, 'odds_decimal': odds, 'shark_score': score, 'confidence': c.get('confidence'), 'value_index': value_index, 'risk_label': c.get('risk_label'), 'stake_hint': stake, 'decision': decision, 'reason': reason, 'payload': c}
        factory.append(item)
    factory.sort(key=lambda x: (x['decision'] != 'PUBLICABLE', -x['value_index'], -x['shark_score']))
    conn = get_db(); cur = conn.cursor()
    if persist:
        for item in factory:
            cur.execute("""
                INSERT INTO shark_pick_factory(source_key,title,league,market,recommended_pick,odds_decimal,shark_score,confidence,value_index,risk_label,stake_hint,decision,reason,payload,status,created_at,updated_at)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (item['source_key'], item['title'], item['league'], item['market'], item['recommended_pick'], str(item['odds_decimal']), item['shark_score'], item['confidence'], item['value_index'], item['risk_label'], item['stake_hint'], item['decision'], item['reason'], json.dumps(item['payload'], ensure_ascii=False), 'draft', madrid_iso_now(), madrid_iso_now()))
            cur.execute("INSERT INTO shark_decision_audit(entity_key,decision,score,reason,payload,created_at) VALUES(?,?,?,?,?,?)", (item['source_key'], item['decision'], item['shark_score'], item['reason'], json.dumps(item, ensure_ascii=False), madrid_iso_now()))
        conn.commit()
    cur.execute("SELECT COUNT(*) AS n FROM shark_pick_factory")
    total_saved = int((cur.fetchone() or {'n':0})['n'] or 0)
    conn.close()
    return {'ok': True, 'version': 'V365', 'persisted': bool(persist), 'generated': len(factory), 'publicables': sum(1 for x in factory if x['decision']=='PUBLICABLE'), 'review': sum(1 for x in factory if x['decision']=='REVISAR'), 'wait': sum(1 for x in factory if x['decision']=='ESPERAR'), 'saved_total': total_saved, 'items': factory[:30], 'updated_at': madrid_iso_now()}


def build_v365_decision_dashboard():
    ensure_v365_schema(); conn = get_db(); cur = conn.cursor()
    out = {'ok': True, 'version': 'V365', 'updated_at': madrid_iso_now()}
    for table in ['shark_pick_factory','shark_history_signals','shark_decision_audit','pick_automation_queue','match_context_snapshots']:
        try:
            cur.execute(f"SELECT COUNT(*) AS n FROM {table}"); out[table] = int((cur.fetchone() or {'n':0})['n'] or 0)
        except Exception: out[table] = 0
    try:
        cur.execute("SELECT decision, COUNT(*) AS n, AVG(value_index) AS avg_value, AVG(shark_score) AS avg_score FROM shark_pick_factory GROUP BY decision")
        out['decision_mix'] = [dict(r) for r in cur.fetchall()]
    except Exception: out['decision_mix'] = []
    try:
        cur.execute("SELECT title, league, recommended_pick, odds_decimal, shark_score, value_index, decision, stake_hint, reason, created_at FROM shark_pick_factory ORDER BY id DESC LIMIT 12")
        out['latest_factory'] = [dict(r) for r in cur.fetchall()]
    except Exception: out['latest_factory'] = []
    try:
        cur.execute("SELECT signal_type, title, score, trend, sample_size, created_at FROM shark_history_signals ORDER BY id DESC LIMIT 12")
        out['latest_signals'] = [dict(r) for r in cur.fetchall()]
    except Exception: out['latest_signals'] = []
    conn.close(); return out


