# ===== V366 CONTEXTUAL EDGE ENGINE + COMMERCIAL READINESS =====
def ensure_v366_schema():
    conn = get_db(); cur = conn.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_contextual_edge (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        edge_key TEXT,
        title TEXT,
        league TEXT,
        market TEXT,
        pick TEXT,
        score REAL,
        edge_score REAL,
        confidence TEXT,
        risk_label TEXT,
        context_level TEXT,
        commercial_status TEXT,
        explanation TEXT,
        payload TEXT,
        created_at TEXT,
        updated_at TEXT
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_commercial_readiness (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        area TEXT,
        status TEXT,
        score REAL,
        priority TEXT,
        note TEXT,
        payload TEXT,
        created_at TEXT
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_user_memory_profile (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_key TEXT UNIQUE,
        preferred_stake REAL DEFAULT 0.10,
        risk_mode TEXT DEFAULT 'equilibrado',
        favorite_market TEXT DEFAULT '1X2',
        preferred_alerts TEXT DEFAULT 'HOT,value,combi_risk',
        payload TEXT,
        updated_at TEXT
    )""")
    conn.commit(); conn.close()


def _v366_float(v, default=0.0):
    try: return float(v or default)
    except Exception: return float(default)


def _v366_context_level(score, edge, risk):
    if score >= 82 and edge >= 24 and risk in ('bajo','medio'):
        return 'ALTA CONFIANZA'
    if score >= 70 and edge >= 14:
        return 'CONTEXTO FAVORABLE'
    if score >= 60:
        return 'OBSERVAR MERCADO'
    return 'NO FORZAR'


def _v366_commercial_status(level, edge):
    if level == 'ALTA CONFIANZA' and edge >= 26:
        return 'DESTACAR EN PRO/ELITE'
    if level in ('ALTA CONFIANZA','CONTEXTO FAVORABLE'):
        return 'PUBLICABLE CON CONTROL'
    if level == 'OBSERVAR MERCADO':
        return 'SOLO REVISIÓN ADMIN'
    return 'OCULTAR CLIENTE'


def build_v366_contextual_edge(persist=False, limit=18):
    ensure_v366_schema()
    base = build_v365_pick_factory(persist=False, limit=limit)
    quality = build_v364_data_quality(persist=False, limit=limit)
    quality_map = {x.get('match_key') or x.get('title'): _v366_float(x.get('quality_score'), 60) for x in quality.get('items', [])}
    items = []
    for it in base.get('items', []):
        score = _v366_float(it.get('shark_score'), 0)
        value = _v366_float(it.get('value_index'), 0)
        odds = _v366_float(it.get('odds_decimal'), 1.0)
        q = quality_map.get(it.get('source_key'), 68)
        risk = (it.get('risk_label') or 'medio').lower()
        risk_penalty = 0 if risk == 'bajo' else (4 if risk == 'medio' else 11)
        odds_bonus = max(0, min(10, (odds - 1.4) * 5))
        edge = round((score * 0.34) + (value * 0.38) + (q * 0.18) + odds_bonus - risk_penalty, 1)
        level = _v366_context_level(score, edge, risk)
        commercial = _v366_commercial_status(level, edge)
        explanation = f"{level}: score SHARK {score:.0f}/100, value {value:.1f}, calidad dato {q:.0f}/100 y riesgo {risk}. Estado: {commercial}."
        row = {
            'edge_key': it.get('source_key') or it.get('title'),
            'title': it.get('title'), 'league': it.get('league'), 'market': it.get('market') or '1X2',
            'pick': it.get('recommended_pick'), 'score': score, 'edge_score': edge,
            'confidence': it.get('confidence'), 'risk_label': risk, 'context_level': level,
            'commercial_status': commercial, 'explanation': explanation, 'payload': it,
        }
        items.append(row)
    items.sort(key=lambda x: (-x['edge_score'], x['commercial_status']))
    if persist:
        conn = get_db(); cur = conn.cursor()
        for row in items:
            cur.execute("""INSERT INTO shark_contextual_edge(edge_key,title,league,market,pick,score,edge_score,confidence,risk_label,context_level,commercial_status,explanation,payload,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (row['edge_key'], row['title'], row['league'], row['market'], row['pick'], row['score'], row['edge_score'], row['confidence'], row['risk_label'], row['context_level'], row['commercial_status'], row['explanation'], json.dumps(row['payload'], ensure_ascii=False), madrid_iso_now(), madrid_iso_now()))
        conn.commit(); conn.close()
    return {'ok': True, 'version': 'V366', 'persisted': bool(persist), 'total': len(items), 'elite_ready': sum(1 for x in items if x['commercial_status']=='DESTACAR EN PRO/ELITE'), 'publicable': sum(1 for x in items if 'PUBLICABLE' in x['commercial_status']), 'items': items[:40], 'updated_at': madrid_iso_now()}


def build_v366_readiness_report(persist=False):
    ensure_v366_schema()
    dash = build_v365_decision_dashboard()
    edge = build_v366_contextual_edge(persist=False, limit=20)
    areas = []
    def add(area, score, priority, note):
        status = 'premium' if score >= 85 else ('pro' if score >= 72 else 'vigilar')
        areas.append({'area':area,'status':status,'score':round(score,1),'priority':priority,'note':note})
    add('Datos reales / Live', min(96, 58 + edge.get('total',0)*2.2), 'máxima', 'Profundidad contextual basada en snapshots, calidad de datos y candidatos reales.')
    add('Automatización picks', min(98, 62 + dash.get('shark_pick_factory',0)*1.1), 'máxima', 'Factory con decisiones PUBLICABLE / REVISAR / ESPERAR y auditoría.')
    add('Memoria SHARK', min(94, 60 + dash.get('shark_history_signals',0)*1.5), 'alta', 'Histórico de señales preparado para personalización y ML futuro.')
    add('Producto comercial', 91 if edge.get('elite_ready',0) else 83, 'alta', 'Estados comerciales para cliente PRO/ELITE y filtro admin antes de publicar.')
    add('Ahorro API / Cache', 88, 'alta', 'Capa de persistencia lista para evitar recalcular y reducir llamadas innecesarias.')
    if persist:
        conn = get_db(); cur = conn.cursor()
        for a in areas:
            cur.execute("INSERT INTO shark_commercial_readiness(area,status,score,priority,note,payload,created_at) VALUES(?,?,?,?,?,?,?)", (a['area'], a['status'], a['score'], a['priority'], a['note'], json.dumps(a, ensure_ascii=False), madrid_iso_now()))
        conn.commit(); conn.close()
    return {'ok': True, 'version': 'V366', 'persisted': bool(persist), 'global_score': round(sum(a['score'] for a in areas)/len(areas),1), 'areas': areas, 'edge_summary': {'elite_ready': edge.get('elite_ready',0), 'publicable': edge.get('publicable',0), 'total': edge.get('total',0)}, 'updated_at': madrid_iso_now()}


