V367_VERSION = "V367_AUTO_OPERATOR_EXPLAINABLE_SHARK"

def ensure_v367_schema():
    ensure_v366_schema()
    conn = get_db(); cur = conn.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_auto_operator_queue(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        signal_key TEXT,
        title TEXT,
        league TEXT,
        market TEXT,
        pick TEXT,
        operator_status TEXT,
        user_message TEXT,
        admin_action TEXT,
        priority_score REAL DEFAULT 0,
        exposure_level TEXT,
        stake_hint TEXT,
        publish_channel TEXT,
        payload TEXT,
        created_at TEXT,
        updated_at TEXT
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_explainable_notes(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        signal_key TEXT,
        title TEXT,
        why_enter TEXT,
        why_wait TEXT,
        risk_note TEXT,
        client_summary TEXT,
        admin_summary TEXT,
        payload TEXT,
        created_at TEXT
    )""")
    conn.commit(); conn.close()


def v367_operator_status(edge_score, commercial_status, risk_label):
    commercial_status = commercial_status or ''
    risk_label = (risk_label or '').lower()
    if edge_score >= 86 and 'DESTACAR' in commercial_status and 'alto' not in risk_label:
        return 'AUTO_PUBLICAR_PRO_ELITE'
    if edge_score >= 78 and 'PUBLICABLE' in commercial_status:
        return 'PUBLICAR_CON_REVISION_RAPIDA'
    if edge_score >= 68:
        return 'MANTENER_EN_OBSERVACION'
    return 'NO_PUBLICAR_AUN'


def v367_stake_hint(edge_score, risk_label):
    risk = (risk_label or '').lower()
    if edge_score >= 88 and 'bajo' in risk:
        return '0,30€ - 0,50€ si la banca lo permite'
    if edge_score >= 78:
        return '0,10€ - 0,25€ enfoque prudente'
    if edge_score >= 68:
        return 'Solo seguimiento, máximo 0,10€ si se entra'
    return 'No recomendado para stake real ahora'


def build_v367_auto_operator(persist=False, limit=24):
    ensure_v367_schema()
    edge = build_v366_contextual_edge(persist=False, limit=limit)
    rows = []
    for x in edge.get('items', []):
        score = float(x.get('edge_score') or 0)
        status = v367_operator_status(score, x.get('commercial_status'), x.get('risk_label'))
        exposure = 'ELITE' if status == 'AUTO_PUBLICAR_PRO_ELITE' else ('PRO' if 'PUBLICAR' in status else ('INTERNO' if 'OBSERVACION' in status else 'OCULTO'))
        channel = 'Cliente + Telegram PRO/ELITE' if exposure in ('PRO','ELITE') else ('Solo admin' if exposure == 'INTERNO' else 'No enviar')
        stake = v367_stake_hint(score, x.get('risk_label'))
        why_enter = f"Señal con edge {score:.1f}/100, estado {x.get('commercial_status')} y pick {x.get('pick') or 'revisar'}."
        why_wait = 'Esperar confirmación live, cuotas o alineaciones si el contexto no está completo.' if score < 86 else 'No esperar demasiado si la cuota mantiene valor, pero validar mercado antes de publicar.'
        risk_note = f"Riesgo detectado: {x.get('risk_label') or 'sin clasificar'}. Stake sugerido: {stake}."
        user_message = f"{x.get('title') or 'Partido'} · {x.get('pick') or 'Pick pendiente'} · {stake}. {why_enter}"
        admin_action = 'Publicar automático para PRO/ELITE' if status == 'AUTO_PUBLICAR_PRO_ELITE' else ('Revisar y publicar' if 'PUBLICAR' in status else ('Vigilar evolución live' if 'OBSERVACION' in status else 'Ocultar por ahora'))
        row = {
            'signal_key': x.get('edge_key'), 'title': x.get('title'), 'league': x.get('league'), 'market': x.get('market'), 'pick': x.get('pick'),
            'operator_status': status, 'priority_score': round(score,1), 'exposure_level': exposure, 'stake_hint': stake,
            'publish_channel': channel, 'user_message': user_message, 'admin_action': admin_action,
            'why_enter': why_enter, 'why_wait': why_wait, 'risk_note': risk_note,
            'commercial_status': x.get('commercial_status'), 'context_level': x.get('context_level'), 'payload': x
        }
        rows.append(row)
    rows.sort(key=lambda r: (-r['priority_score'], r['operator_status']))
    if persist:
        conn = get_db(); cur = conn.cursor()
        for r in rows:
            cur.execute("""INSERT INTO shark_auto_operator_queue(signal_key,title,league,market,pick,operator_status,user_message,admin_action,priority_score,exposure_level,stake_hint,publish_channel,payload,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (r['signal_key'], r['title'], r['league'], r['market'], r['pick'], r['operator_status'], r['user_message'], r['admin_action'], r['priority_score'], r['exposure_level'], r['stake_hint'], r['publish_channel'], json.dumps(r, ensure_ascii=False), madrid_iso_now(), madrid_iso_now()))
            cur.execute("""INSERT INTO shark_explainable_notes(signal_key,title,why_enter,why_wait,risk_note,client_summary,admin_summary,payload,created_at)
                           VALUES(?,?,?,?,?,?,?,?,?)""", (r['signal_key'], r['title'], r['why_enter'], r['why_wait'], r['risk_note'], r['user_message'], r['admin_action'], json.dumps(r, ensure_ascii=False), madrid_iso_now()))
        conn.commit(); conn.close()
    counts = {k: sum(1 for r in rows if r['operator_status']==k) for k in ['AUTO_PUBLICAR_PRO_ELITE','PUBLICAR_CON_REVISION_RAPIDA','MANTENER_EN_OBSERVACION','NO_PUBLICAR_AUN']}
    return {'ok': True, 'version': 'V367', 'persisted': bool(persist), 'total': len(rows), 'counts': counts, 'items': rows[:limit], 'updated_at': madrid_iso_now()}


def build_v367_commercial_command_center(persist=False):
    ensure_v367_schema()
    op = build_v367_auto_operator(persist=persist, limit=30)
    total = op.get('total', 0) or 1
    auto = op['counts'].get('AUTO_PUBLICAR_PRO_ELITE',0)
    review = op['counts'].get('PUBLICAR_CON_REVISION_RAPIDA',0)
    obs = op['counts'].get('MANTENER_EN_OBSERVACION',0)
    commercial_power = round(min(99, 72 + auto*5 + review*3 + obs*1.2), 1)
    safety = round(max(70, 96 - op['counts'].get('NO_PUBLICAR_AUN',0)*1.5), 1)
    return {
        'ok': True, 'version': 'V367', 'commercial_power': commercial_power, 'safety_filter': safety,
        'automation_level': 'alto' if auto+review >= 4 else ('medio' if auto+review else 'preparación'),
        'summary': {
            'auto_publish': auto, 'quick_review': review, 'watchlist': obs, 'hidden': op['counts'].get('NO_PUBLICAR_AUN',0),
            'usable_percent': round(((auto+review+obs)/total)*100,1)
        },
        'recommended_next_step': 'Conectar publicación real a Telegram/Push por membresía y guardar resultado final de cada señal.',
        'items': op.get('items', [])[:12], 'updated_at': madrid_iso_now()
    }


