def _v371_pick_from_profile(row):
    src = row.get('source') or {}
    confidence_memory = _v371_safe_float(row.get('confidence_memory'), 55)
    commercial_priority = _v371_safe_float(row.get('commercial_priority'), 55)
    fatigue_pressure = _v371_safe_float(row.get('fatigue_pressure'), 45)
    historical_strength = _v371_safe_float(row.get('historical_strength'), 55)
    live_trend_strength = _v371_safe_float(row.get('live_trend_strength'), 55)
    odds = _v371_safe_float(src.get('odds') or src.get('cuota') or src.get('estimated_odds'), 1.75)
    market = src.get('market') or '1X2'
    pick = src.get('pick') or src.get('selection') or 'Entrada prudente 1X2'
    a = row.get('team_a') or src.get('team_a') or src.get('home_team') or 'Local'
    b = row.get('team_b') or src.get('team_b') or src.get('away_team') or 'Visitante'
    league = row.get('league') or src.get('league') or 'Competición'
    value_index = max(0, min(100, confidence_memory * 0.36 + commercial_priority * 0.28 + historical_strength * 0.18 + live_trend_strength * 0.18 - fatigue_pressure * 0.22 + min(12, max(0, odds-1.50)*8)))
    risk = max(0, min(100, fatigue_pressure * 0.58 + (100-confidence_memory) * 0.24 + (100-live_trend_strength) * 0.18))
    confidence = max(0, min(100, confidence_memory * 0.55 + value_index * 0.30 + (100-risk) * 0.15))
    # stake pensado para usuarios que prueban combis pequeñas tipo 0,10€, prudente y explicable.
    if risk >= 75 or confidence < 55:
        publish_state = 'ESPERAR'
        tier = 'FREE'
        stake_micro = 0.00
    elif value_index >= 78 and confidence >= 72 and risk <= 45:
        publish_state = 'PUBLICABLE_PREMIUM'
        tier = 'ELITE'
        stake_micro = 0.10
    elif value_index >= 66 and confidence >= 63 and risk <= 58:
        publish_state = 'PUBLICABLE_CONTROLADA'
        tier = 'PRO'
        stake_micro = 0.05
    else:
        publish_state = 'VIGILAR'
        tier = 'FREE'
        stake_micro = 0.00
    autopilot_key = f"{league}|{a}|{b}|{market}|{pick}|{publish_state}"[:240]
    user_explanation = f"{a} vs {b}: SHARK detecta índice de valor {value_index:.0f}/100, confianza {confidence:.0f}/100 y riesgo {risk:.0f}/100. Estado: {publish_state.replace('_',' ').lower()}."
    admin_explanation = f"Autopilot V371: tier={tier}, stake_micro={stake_micro:.2f}€, histórico={historical_strength:.1f}, live={live_trend_strength:.1f}, presión={fatigue_pressure:.1f}, cuota≈{odds:.2f}."
    return {
        'autopilot_key': autopilot_key, 'team_a': a, 'team_b': b, 'league': league, 'market': market, 'pick': pick,
        'confidence': round(confidence,1), 'risk': round(risk,1), 'value_index': round(value_index,1),
        'stake_micro': round(stake_micro,2), 'release_tier': tier, 'publish_state': publish_state,
        'user_explanation': user_explanation, 'admin_explanation': admin_explanation, 'source': row
    }


