def _v372_profile_from_autopilot(row):
    src = row.get('source') or row.get('payload') or row
    if isinstance(src, str):
        try: src = json.loads(src)
        except Exception: src = {}
    a = row.get('team_a') or src.get('team_a') or src.get('home_team') or 'Local'
    b = row.get('team_b') or src.get('team_b') or src.get('away_team') or 'Visitante'
    league = row.get('league') or src.get('league') or 'Competición'
    confidence = _v372_safe_float(row.get('confidence') or src.get('confidence'), 60)
    risk = _v372_safe_float(row.get('risk') or src.get('risk'), 50)
    value_index = _v372_safe_float(row.get('value_index') or src.get('value_index'), 55)
    live_strength = _v372_safe_float(src.get('live_trend_strength') or src.get('pressure_score') or src.get('momentum'), 55)
    fatigue = _v372_safe_float(src.get('fatigue_pressure') or src.get('trap_risk'), 45)
    odds = _v372_safe_float(src.get('odds') or src.get('cuota') or src.get('estimated_odds'), 1.75)

    tempo_score = max(0, min(100, live_strength * 0.62 + value_index * 0.20 + max(0, odds-1.40)*8))
    chaos_score = max(0, min(100, risk * 0.55 + fatigue * 0.30 + abs(odds-1.85)*12))
    pressure_score = max(0, min(100, live_strength * 0.50 + confidence * 0.28 + value_index * 0.22))
    trap_risk = max(0, min(100, chaos_score * 0.52 + (100-confidence) * 0.25 + fatigue * 0.23))
    favorite_stability = max(0, min(100, confidence * 0.46 + (100-risk) * 0.30 + value_index * 0.24))
    live_reliability = max(0, min(100, (100-chaos_score) * 0.40 + pressure_score * 0.35 + confidence * 0.25))
    commercial_priority = max(0, min(100, value_index * 0.42 + favorite_stability * 0.30 + live_reliability * 0.20 - trap_risk * 0.18 + pressure_score * 0.10))

    if chaos_score >= 72 and trap_risk >= 65:
        profile_type = 'PARTIDO_TRAMPA'
        shark_read = 'Esperar confirmación: hay demasiada volatilidad para venderlo como pick fuerte.'
    elif tempo_score >= 72 and pressure_score >= 68 and trap_risk < 55:
        profile_type = 'PARTIDO_HOT_CONTROLADO'
        shark_read = 'Buen escenario para vigilancia premium: ritmo alto con presión útil y riesgo controlado.'
    elif tempo_score < 42 and pressure_score < 50:
        profile_type = 'PARTIDO_LENTO'
        shark_read = 'Partido frío: evitar forzar entrada salvo cuota muy concreta.'
    elif favorite_stability < 45:
        profile_type = 'FAVORITO_INESTABLE'
        shark_read = 'El favorito no está suficientemente estable; revisar antes de publicar.'
    else:
        profile_type = 'PARTIDO_EQUILIBRADO'
        shark_read = 'Escenario aceptable, pero necesita filtro SHARK antes de subirlo de tier.'

    personality_key = f"{league}|{a}|{b}|{profile_type}"[:240]
    client_summary = f"{a} vs {b}: perfil {profile_type.replace('_',' ').lower()}, prioridad {commercial_priority:.0f}/100 y fiabilidad live {live_reliability:.0f}/100. {shark_read}"
    admin_summary = f"V372 Personality: tempo={tempo_score:.1f}, caos={chaos_score:.1f}, presión={pressure_score:.1f}, trampa={trap_risk:.1f}, estabilidad={favorite_stability:.1f}."
    return {
        'personality_key': personality_key, 'team_a': a, 'team_b': b, 'league': league,
        'profile_type': profile_type, 'tempo_score': round(tempo_score,1), 'chaos_score': round(chaos_score,1),
        'pressure_score': round(pressure_score,1), 'trap_risk': round(trap_risk,1),
        'favorite_stability': round(favorite_stability,1), 'live_reliability': round(live_reliability,1),
        'commercial_priority': round(commercial_priority,1), 'shark_read': shark_read,
        'client_summary': client_summary, 'admin_summary': admin_summary, 'source': row
    }


def build_v372_match_personality_engine(persist=False, limit=40):
    ensure_v372_schema()
    try:
        base = build_v371_real_picks_autopilot(persist=False, limit=max(40, limit))
        source_items = base.get('items', [])
    except Exception:
        source_items = []
    rows = [_v372_profile_from_autopilot(x) for x in source_items]
    rows.sort(key=lambda r: (-r['commercial_priority'], r['trap_risk'], -r['live_reliability']))
    counts = {}
    for r in rows:
        counts[r['profile_type']] = counts.get(r['profile_type'], 0) + 1
    if persist:
        conn = get_db(); cur = conn.cursor(); now = madrid_iso_now()
        for r in rows:
            payload = json.dumps(r, ensure_ascii=False)
            cur.execute("""INSERT OR REPLACE INTO shark_match_personality_v372(personality_key,team_a,team_b,league,profile_type,tempo_score,chaos_score,pressure_score,trap_risk,favorite_stability,live_reliability,commercial_priority,shark_read,client_summary,admin_summary,payload,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
                r['personality_key'], r['team_a'], r['team_b'], r['league'], r['profile_type'], r['tempo_score'], r['chaos_score'], r['pressure_score'], r['trap_risk'], r['favorite_stability'], r['live_reliability'], r['commercial_priority'], r['shark_read'], r['client_summary'], r['admin_summary'], payload, now, now
            ))
            ckey = ('livectx|' + r['personality_key'])[:240]
            hint = 'PUBLICAR_PREMIUM' if r['profile_type']=='PARTIDO_HOT_CONTROLADO' and r['commercial_priority']>=72 else ('BLOQUEAR' if r['profile_type']=='PARTIDO_TRAMPA' else 'VIGILAR')
            cur.execute("""INSERT OR REPLACE INTO shark_live_context_memory_v372(context_key,personality_key,context_type,intensity,decision_hint,payload,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?)""", (ckey, r['personality_key'], r['profile_type'], r['commercial_priority'], hint, payload, now, now))
        conn.commit(); conn.close()
    return {'ok': True, 'version': V372_VERSION, 'persisted': bool(persist), 'total': len(rows), 'counts': counts, 'items': rows[:limit], 'updated_at': madrid_iso_now()}


@app.route('/api/v372/match-personality')
def api_v372_match_personality():
    persist = request.args.get('persist', '0') in ('1','true','si','yes')
    limit = int(request.args.get('limit', 40) or 40)
    return jsonify(build_v372_match_personality_engine(persist=persist, limit=limit))


