V376_VERSION = "V376.0_MOMENTUM_RADAR_RENDER_READY"


def ensure_v376_schema():
    """Tablas ligeras para preparar momentum/live sin gastar API extra."""
    conn = get_db(); cur = conn.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_momentum_radar_v376(
        radar_key TEXT PRIMARY KEY,
        match_label TEXT,
        league TEXT,
        radar_state TEXT,
        momentum_score REAL,
        pressure_score REAL,
        chaos_score REAL,
        stability_score REAL,
        shark_hint TEXT,
        payload TEXT,
        created_at TEXT,
        updated_at TEXT
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS shark_release_guard_v376(
        guard_key TEXT PRIMARY KEY,
        guard_type TEXT,
        status TEXT,
        detail TEXT,
        payload TEXT,
        created_at TEXT,
        updated_at TEXT
    )""")
    conn.commit(); conn.close()


def _v376_float(value, default=0.0):
    try:
        if value in (None, ''):
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _v376_radar_from_personality(row):
    src = row or {}
    a = src.get('team_a') or 'Local'
    b = src.get('team_b') or 'Visitante'
    league = src.get('league') or 'Competición'
    tempo = _v376_float(src.get('tempo_score'), 55)
    pressure = _v376_float(src.get('pressure_score'), 55)
    chaos = _v376_float(src.get('chaos_score'), 45)
    trap = _v376_float(src.get('trap_risk'), 45)
    reliability = _v376_float(src.get('live_reliability'), 55)
    commercial = _v376_float(src.get('commercial_priority'), 55)
    momentum_score = max(0, min(100, tempo*0.34 + pressure*0.32 + commercial*0.20 + reliability*0.14))
    chaos_score = max(0, min(100, chaos*0.58 + trap*0.42))
    stability_score = max(0, min(100, reliability*0.45 + (100-chaos_score)*0.35 + commercial*0.20))
    if momentum_score >= 74 and stability_score >= 62 and chaos_score < 58:
        state = 'HOT_CONTROLADO'
        hint = 'Señal premium: momentum fuerte con estabilidad suficiente. Candidata para vigilancia PRO/ELITE.'
    elif chaos_score >= 72:
        state = 'CAOTICO'
        hint = 'No forzar: partido demasiado volátil. Mejor esperar confirmación.'
    elif stability_score < 45:
        state = 'INESTABLE'
        hint = 'Riesgo alto: SHARK recomienda revisar antes de publicar.'
    elif momentum_score >= 62:
        state = 'PRESION_ACTIVA'
        hint = 'Hay presión útil, pero no suficiente para venderla como entrada fuerte.'
    else:
        state = 'CONTROLADO_FRIO'
        hint = 'Partido estable pero frío. Evitar sobrecargar combinadas.'
    key = f"{league}|{a}|{b}|{state}"[:240]
    return {
        'radar_key': key,
        'match_label': f'{a} vs {b}',
        'league': league,
        'radar_state': state,
        'momentum_score': round(momentum_score, 1),
        'pressure_score': round(pressure, 1),
        'chaos_score': round(chaos_score, 1),
        'stability_score': round(stability_score, 1),
        'shark_hint': hint,
        'source': src,
    }


def build_v376_momentum_radar(persist=False, limit=40):
    ensure_v376_schema()
    try:
        base = build_v372_match_personality_engine(persist=False, limit=max(limit, 40))
        items = base.get('items', [])
    except Exception:
        items = []
    rows = [_v376_radar_from_personality(x) for x in items]
    rows.sort(key=lambda r: (-r['momentum_score'], -r['stability_score'], r['chaos_score']))
    counts = {}
    for r in rows:
        counts[r['radar_state']] = counts.get(r['radar_state'], 0) + 1
    if persist:
        conn = get_db(); cur = conn.cursor(); now = madrid_iso_now()
        for r in rows:
            cur.execute("""INSERT OR REPLACE INTO shark_momentum_radar_v376(radar_key,match_label,league,radar_state,momentum_score,pressure_score,chaos_score,stability_score,shark_hint,payload,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""", (
                r['radar_key'], r['match_label'], r['league'], r['radar_state'], r['momentum_score'], r['pressure_score'], r['chaos_score'], r['stability_score'], r['shark_hint'], json.dumps(r, ensure_ascii=False), now, now
            ))
        conn.commit(); conn.close()
    return {'ok': True, 'version': V376_VERSION, 'app_version': APP_VERSION, 'persisted': bool(persist), 'total': len(rows), 'counts': counts, 'items': rows[:limit], 'updated_at': madrid_iso_now()}


