# ==========================================================
# V436 FUNCTIONAL CORE FLOW — cliente/admin funcionando y ordenado
# ==========================================================
V436_VERSION = "V436.0 · Functional Core Flow"


def v436_safe_get(row, key, default=""):
    try:
        return row[key] if row and key in row.keys() else default
    except Exception:
        try:
            return row.get(key, default) if row else default
        except Exception:
            return default


def v436_real_feed(force=False):
    try:
        from core.real_core_engine import RealCoreEngine
        return RealCoreEngine.fetch(force=force)
    except Exception as exc:
        return {
            "ok": False,
            "source": "safe",
            "message": "No hay datos reales disponibles ahora mismo. La pantalla funciona sin demos.",
            "error": str(exc)[:180],
            "matches": [],
            "buckets": {"live": [], "today": [], "upcoming": []},
            "counts": {"total": 0, "live": 0, "today": 0, "upcoming": 0},
        }


def v436_matches(feed, mode="all", limit=12):
    try:
        buckets = feed.get("buckets") or {}
        if mode == "live":
            data = buckets.get("live") or []
        elif mode == "today":
            data = buckets.get("today") or []
        else:
            data = feed.get("matches") or []
            if not data:
                data = (buckets.get("live") or []) + (buckets.get("today") or []) + (buckets.get("upcoming") or [])
        return list(data)[:limit]
    except Exception:
        return []


def v436_pick_rows(limit=12):
    try:
        conn = get_db(); cur = conn.cursor()
        cur.execute("""
            SELECT * FROM picks
            WHERE COALESCE(active,1)=1
            ORDER BY COALESCE(score,0) DESC, id DESC
            LIMIT ?
        """, (limit,))
        rows = cur.fetchall(); conn.close()
        return rows
    except Exception:
        return []


def v436_combi_summary():
    rows = v436_pick_rows(8)
    selections = []
    odds_total = 1.0
    for r in rows[:4]:
        cuota = safe_float(v436_safe_get(r, "cuota", 0), 0) or safe_float(v436_safe_get(r, "odds", 0), 0)
        if cuota <= 1: cuota = 1.35
        odds_total *= cuota
        selections.append({
            "title": v436_safe_get(r, "title", "Partido real pendiente"),
            "pick": v436_safe_get(r, "pick", v436_safe_get(r, "market", "1X2")),
            "odds": round(cuota, 2),
            "score": int(safe_float(v436_safe_get(r, "score", 70), 70)),
        })
    stake = 0.10
    return {"selections": selections, "total_odds": round(odds_total if selections else 0, 2), "stake": stake, "return": round((odds_total * stake) if selections else 0, 2)}


def v436_functional_status():
    return {
        "version": V436_VERSION,
        "client_routes": ["/clientes", "/cliente/live", "/cliente/picks", "/cliente/combi", "/cliente/shark", "/cuenta"],
        "admin_routes": ["/admin", "/admin/memberships", "/admin/api-control", "/admin/v415-ml-ops"],
        "checked": ["login", "home", "live", "picks", "combi", "shark", "cuenta", "admin"],
        "policy": "Cliente limpio, admin separado, sin demos inventadas, pantallas funcionales aunque falten datos externos.",
    }


