def v436_admin_main():
    gate = require_admin()
    if gate: return gate
    stats = {"users":0,"premium":0,"picks":0,"telegram":0}
    try:
        conn=get_db(); cur=conn.cursor()
        cur.execute("SELECT COUNT(*) FROM users"); stats["users"]=cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM users WHERE plan IN ('PRO','ELITE','ADMIN')"); stats["premium"]=cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM picks"); stats["picks"]=cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM users WHERE COALESCE(telegram_chat_id,'')!=''"); stats["telegram"]=cur.fetchone()[0]
        conn.close()
    except Exception:
        pass
    return render_template("admin/v436_functional_admin.html", stats=stats, status=v436_functional_status(), centers=v435_admin_flow(), version=V436_VERSION)


