def v437_safe_count(table):
    try:
        conn = get_db(); cur = conn.cursor()
        cur.execute(f"SELECT COUNT(*) FROM {table}")
        value = cur.fetchone()[0]
        conn.close()
        return int(value or 0)
    except Exception:
        return 0


