# =================== V443 TELEGRAM LIVE DELIVERY BRIDGE ===================
# Objetivo: si el test del bot/canal funciona, que también salgan picks y partidos reales.
# Causa típica arreglada: Telegram estaba conectado, pero la cola de señales dependía de filtros
# demasiado estrictos, picks ya marcados o fixtures no sincronizados. Este puente añade envío manual
# real y diagnóstico claro para admin sin enseñar nada técnico al cliente.
V443_VERSION = "V443_TELEGRAM_LIVE_DELIVERY_BRIDGE"


def v443_telegram_targets(include_test=True):
    """Destinos reales disponibles. Deduplica canal único, planes y test."""
    targets, seen = [], set()
    raw = [
        ("general", TELEGRAM_CHAT_ID),
        ("free", TELEGRAM_FREE_CHAT_ID),
        ("pro", TELEGRAM_PRO_CHAT_ID),
        ("elite", TELEGRAM_ELITE_CHAT_ID),
    ]
    if include_test:
        raw.append(("test", TELEGRAM_TEST_CHAT_ID))
    for label, chat_id in raw:
        chat_id = str(chat_id or "").strip()
        if chat_id and chat_id not in seen:
            targets.append({"label": label, "chat_id": chat_id})
            seen.add(chat_id)
    return targets


def v443_tg_send(chat_id, body, kind="v443_delivery", title="NeMeSiS SHARK PRO", payload=None):
    """Envío robusto: usa retry si existe y deja log claro."""
    if 'send_telegram_message_with_retry' in globals():
        return send_telegram_message_with_retry(chat_id, body, kind=kind, title=title, payload=payload or {})
    return send_telegram_message(chat_id, body, kind=kind, title=title, payload=payload or {})


def v443_real_fixture_rows(limit=8, filter_name='today', force_sync=True):
    """Busca partidos reales cacheados; si está vacío, intenta refrescar RealCore y sincronizar fixtures."""
    rows = []
    try:
        from fixtures_connector_v146.core import list_fixtures, sync_fixtures, ensure_schema
        ensure_schema()
        rows = list_fixtures(filter_name or 'today', limit=int(limit or 8))
        if force_sync and not rows:
            feed = None
            if 'RealCoreEngine' in globals():
                try: feed = RealCoreEngine.fetch(force=True)
                except Exception: feed = None
            if not feed:
                try:
                    from core.real_core_engine import RealCoreEngine as _RCE
                    feed = _RCE.fetch(force=True)
                except Exception:
                    feed = None
            matches = (feed or {}).get('matches') or []
            if matches:
                sync_fixtures(matches, source='v443_real_core_force')
                rows = list_fixtures(filter_name or 'today', limit=int(limit or 8))
                if not rows and filter_name == 'today':
                    rows = list_fixtures('upcoming', limit=int(limit or 8))
        if not rows and filter_name == 'today':
            rows = list_fixtures('upcoming', limit=int(limit or 8))
    except Exception as e:
        try: log_alert('v443_fixtures', 'Error leyendo partidos', str(e)[:300], 'system', 'error', {})
        except Exception: pass
    return rows[:int(limit or 8)]


def v443_format_fixture_line(f):
    home = _html_escape(f.get('home_team') or f.get('home') or 'Local')
    away = _html_escape(f.get('away_team') or f.get('away') or 'Visitante')
    league = _html_escape(f.get('league') or 'Competición')
    kickoff = _html_escape(f.get('kickoff') or f.get('commence_time') or 'Horario pendiente')
    status = str(f.get('status') or '').lower()
    minute = _html_escape(f.get('minute') or '')
    score = f.get('score') or ''
    if not score and f.get('score_home') is not None and f.get('score_away') is not None:
        score = f"{f.get('score_home')}-{f.get('score_away')}"
    live = ' 🔴 LIVE' if status in ('live','inplay','in_play','1h','2h','ht','en directo','en vivo') else ''
    score_txt = f" · <b>{_html_escape(score)}</b>" if score and score != 'N/A' else ''
    min_txt = f" · {minute}" if minute else ''
    return f"• <b>{home} vs {away}</b>{live}\n  🏆 {league}\n  🕒 {kickoff}{score_txt}{min_txt}"


def v443_build_fixtures_message(filter_name='today', limit=8):
    rows = v443_real_fixture_rows(limit=limit, filter_name=filter_name, force_sync=True)
    if not rows:
        return None, []
    title = 'Partidos de hoy' if filter_name == 'today' else ('Partidos LIVE' if filter_name == 'live' else 'Próximos partidos')
    lines = [
        f"🦈 <b>NeMeSiS SHARK PRO · {title}</b>",
        "Resumen real listo para el canal. Sin demos ni datos inventados.",
        "",
    ]
    for f in rows[:int(limit or 8)]:
        lines.append(v443_format_fixture_line(f)); lines.append('')
    lines.append("Abre la app para ver Match Center, escudos, picks y análisis SHARK.")
    return "\n".join(lines).strip(), rows


def v443_send_fixtures(filter_name='today', limit=8, target='auto'):
    if not TELEGRAM_BOT_TOKEN:
        return {'ok': False, 'reason': 'missing_bot_token', 'sent': 0}
    targets = v443_telegram_targets(include_test=True)
    if target and target != 'auto':
        targets = [t for t in targets if t['label'] == target]
    if not targets:
        return {'ok': False, 'reason': 'no_channel_target', 'sent': 0}
    body, rows = v443_build_fixtures_message(filter_name=filter_name, limit=limit)
    if not body:
        log_alert('v443_fixtures', 'Sin partidos para Telegram', 'No hay partidos reales cacheados ni disponibles tras sincronizar.', 'telegram', 'empty', {'filter': filter_name})
        return {'ok': False, 'reason': 'no_real_fixtures_available', 'sent': 0, 'fixtures': 0}
    sent, results = 0, []
    for t in targets:
        res = v443_tg_send(t['chat_id'], body, kind='v443_fixtures', title='Partidos reales', payload={'target': t['label'], 'filter': filter_name, 'fixtures': len(rows)})
        results.append({'target': t['label'], **(res or {})})
        if res and res.get('ok'): sent += 1
    return {'ok': sent > 0, 'sent': sent, 'fixtures': len(rows), 'results': results}


def v443_best_pick_rows(limit=5):
    """Busca señales reales activas sin exigir que superen filtros de envío automático."""
    try:
        conn = get_db(); cur = conn.cursor()
        cur.execute("""
            SELECT * FROM picks
            WHERE COALESCE(active,1)=1
            ORDER BY CAST(COALESCE(score,0) AS INTEGER) DESC, id DESC
            LIMIT ?
        """, (int(limit or 5),))
        rows = cur.fetchall(); conn.close()
        return rows
    except Exception:
        return []


def v443_send_best_pick(target='auto', force=True):
    if not TELEGRAM_BOT_TOKEN:
        return {'ok': False, 'reason': 'missing_bot_token', 'sent': 0}
    targets = v443_telegram_targets(include_test=True)
    if target and target != 'auto':
        targets = [t for t in targets if t['label'] == target]
    if not targets:
        return {'ok': False, 'reason': 'no_channel_target', 'sent': 0}
    picks = v443_best_pick_rows(10)
    if not picks:
        log_alert('v443_pick', 'Sin picks para Telegram', 'No hay picks activos guardados para enviar.', 'telegram', 'empty', {})
        return {'ok': False, 'reason': 'no_active_picks', 'sent': 0}
    pick = picks[0]
    body = build_pick_alert_message(pick, prefix='Señal SHARK') if 'build_pick_alert_message' in globals() else build_channel_pick_message(pick, 'PRO')
    body = "🦈 <b>NeMeSiS SHARK PRO · Señal destacada</b>\n\n" + body
    sent, results = 0, []
    for t in targets:
        res = v443_tg_send(t['chat_id'], body, kind='v443_force_pick', title='Señal destacada', payload={'target': t['label'], 'pick_id': safe_row_get(pick, 'id')})
        results.append({'target': t['label'], **(res or {})})
        if res and res.get('ok'): sent += 1
    if sent:
        try: mark_pick_telegram_alerted(safe_row_get(pick, 'id'), 'telegram_channel_alerted_at')
        except Exception: pass
    return {'ok': sent > 0, 'sent': sent, 'pick_id': safe_row_get(pick, 'id'), 'results': results}


def v443_delivery_status():
    picks = v443_best_pick_rows(20)
    fixtures_today = v443_real_fixture_rows(20, 'today', force_sync=False)
    fixtures_live = v443_real_fixture_rows(20, 'live', force_sync=False)
    return {
        'version': V443_VERSION,
        'bot_token': bool(TELEGRAM_BOT_TOKEN),
        'alerts_enabled': bool(ENABLE_PRO_ALERTS),
        'targets': [{'label': t['label'], 'preview': str(t['chat_id'])[:6] + '…' + str(t['chat_id'])[-4:]} for t in v443_telegram_targets(True)],
        'targets_count': len(v443_telegram_targets(True)),
        'active_picks': len(picks),
        'fixtures_today': len(fixtures_today),
        'fixtures_live': len(fixtures_live),
        'likely_blockers': [x for x in [
            'Falta TELEGRAM_BOT_TOKEN' if not TELEGRAM_BOT_TOKEN else '',
            'No hay TELEGRAM_CHAT_ID / canales por plan configurados' if not v443_telegram_targets(True) else '',
            'No hay picks activos guardados' if not picks else '',
            'No hay partidos cacheados todavía; usa Enviar partidos o refresca Real Core' if not (fixtures_today or fixtures_live) else '',
            'ENABLE_PRO_ALERTS está apagado: el test puede funcionar si se fuerza, pero el auto-envío queda bloqueado' if not ENABLE_PRO_ALERTS else '',
        ] if x],
        'policy': 'Bot/canal funcionando no significa que haya cola de picks/partidos. V443 une diagnóstico + envío real manual + fallback de sincronización.',
    }


