# =================== V444 DELIVERY RELIABILITY COMMAND CENTER ===================
# Objetivo: que Telegram/picks/partidos no dependan de mirar 4 sitios distintos.
# Este centro valida el flujo completo: datos disponibles -> picks activos -> destino Telegram -> envío real -> logs.
V444_VERSION = "V444_DELIVERY_RELIABILITY_COMMAND_CENTER"


def v444_safe_count(table, where="1=1"):
    try:
        conn = get_db(); cur = conn.cursor()
        cur.execute(f"SELECT COUNT(*) AS c FROM {table} WHERE {where}")
        row = cur.fetchone(); conn.close()
        return int((row[0] if row else 0) or 0)
    except Exception:
        return 0


def v444_recent_alerts(limit=20):
    try:
        conn = get_db(); cur = conn.cursor()
        cur.execute("""
            SELECT kind, title, channel, status, created_at
            FROM alert_logs
            ORDER BY id DESC
            LIMIT ?
        """, (int(limit or 20),))
        rows = [dict(r) for r in cur.fetchall()]
        conn.close(); return rows
    except Exception:
        return []


def v444_delivery_health():
    status = v443_delivery_status() if 'v443_delivery_status' in globals() else {}
    picks = v443_best_pick_rows(10) if 'v443_best_pick_rows' in globals() else []
    fixtures_today = v443_real_fixture_rows(12, 'today', force_sync=False) if 'v443_real_fixture_rows' in globals() else []
    fixtures_live = v443_real_fixture_rows(12, 'live', force_sync=False) if 'v443_real_fixture_rows' in globals() else []
    blockers = list(status.get('likely_blockers') or [])
    score = 100
    if not status.get('bot_token'): score -= 35
    if not status.get('targets_count'): score -= 30
    if not picks: score -= 15
    if not (fixtures_today or fixtures_live): score -= 15
    if blockers: score -= min(20, len(blockers)*5)
    score = max(0, min(100, score))
    if score >= 85: label = 'LISTO'
    elif score >= 60: label = 'REVISAR'
    else: label = 'BLOQUEADO'
    return {
        'version': V444_VERSION,
        'score': score,
        'label': label,
        'bot_token': bool(status.get('bot_token')),
        'targets_count': int(status.get('targets_count') or 0),
        'targets': status.get('targets') or [],
        'active_picks': len(picks),
        'fixtures_today': len(fixtures_today),
        'fixtures_live': len(fixtures_live),
        'blockers': blockers,
        'recent_alerts': v444_recent_alerts(20),
        'checks': [
            {'name': 'Bot Telegram', 'ok': bool(status.get('bot_token')), 'hint': 'Token cargado' if status.get('bot_token') else 'Falta TELEGRAM_BOT_TOKEN'},
            {'name': 'Canales/destinos', 'ok': int(status.get('targets_count') or 0) > 0, 'hint': f"{int(status.get('targets_count') or 0)} destinos detectados"},
            {'name': 'Picks activos', 'ok': len(picks) > 0, 'hint': f"{len(picks)} picks listos" if picks else 'No hay picks activos guardados'},
            {'name': 'Partidos cacheados', 'ok': bool(fixtures_today or fixtures_live), 'hint': f"Hoy {len(fixtures_today)} · Live {len(fixtures_live)}"},
            {'name': 'Anti-spam visual', 'ok': True, 'hint': 'Un resumen principal y botones manuales'},
        ]
    }


def v444_build_digest_message():
    fixtures_body, fixtures = v443_build_fixtures_message('today', 5) if 'v443_build_fixtures_message' in globals() else (None, [])
    picks = v443_best_pick_rows(3) if 'v443_best_pick_rows' in globals() else []
    lines = [
        '🦈 <b>NeMeSiS SHARK PRO · Resumen SHARK</b>',
        'Resumen limpio para el canal. Partidos + señal destacada sin spam.',
        ''
    ]
    if fixtures:
        lines.append('⚽ <b>Partidos principales</b>')
        for f in fixtures[:5]:
            lines.append(v443_format_fixture_line(f) if 'v443_format_fixture_line' in globals() else f"• {f}")
            lines.append('')
    else:
        lines.append('⚽ Partidos: todavía no hay partidos cacheados.')
        lines.append('')
    if picks:
        p = picks[0]
        title = safe_row_get(p, 'title', '') or safe_row_get(p, 'match_name', '') or 'Señal SHARK'
        market = safe_row_get(p, 'market', '') or safe_row_get(p, 'pick', '') or 'Mercado recomendado'
        odd = safe_row_get(p, 'odd', '') or safe_row_get(p, 'odds', '') or ''
        score = safe_row_get(p, 'score', '') or safe_row_get(p, 'confidence', '') or ''
        lines.extend([
            '🎯 <b>Señal destacada</b>',
            f"• <b>{_html_escape(title)}</b>",
            f"  Mercado: {_html_escape(market)}" + (f" · Cuota: {_html_escape(odd)}" if odd else ''),
            f"  SHARK Score: {_html_escape(score)}" if score else '  SHARK: revisar en app',
            ''
        ])
    else:
        lines.append('🎯 Señal destacada: todavía no hay picks activos guardados.')
        lines.append('')
    lines.append('Abre la app para ver Live Center, picks, combinadas y análisis completo.')
    return '\n'.join(lines).strip()


def v444_send_daily_digest(target='auto'):
    if not TELEGRAM_BOT_TOKEN:
        return {'ok': False, 'reason': 'missing_bot_token', 'sent': 0}
    targets = v443_telegram_targets(include_test=True) if 'v443_telegram_targets' in globals() else []
    if target and target != 'auto':
        targets = [t for t in targets if t.get('label') == target]
    if not targets:
        return {'ok': False, 'reason': 'no_targets', 'sent': 0}
    body = v444_build_digest_message()
    sent, results = 0, []
    for t in targets:
        res = v443_tg_send(t['chat_id'], body, kind='v444_digest', title='Resumen SHARK', payload={'target': t.get('label')}) if 'v443_tg_send' in globals() else send_telegram_message(t['chat_id'], body, kind='v444_digest', title='Resumen SHARK', payload={'target': t.get('label')})
        results.append({'target': t.get('label'), **(res or {})})
        if res and res.get('ok'): sent += 1
    return {'ok': sent > 0, 'sent': sent, 'results': results}


