# =================== V454 PUBLIC SPORTS FIRST HOME ===================
# La app ya no arranca como landing/panel. Arranca como una portada deportiva pública
# tipo Flashscore/SofaScore: partidos de hoy, live, picks y acceso claro a login/registro.
V454_VERSION = "V454_PUBLIC_SPORTS_FIRST_HOME"
APP_VERSION = V454_VERSION


def _v454_row_to_dict(row):
    try:
        if hasattr(row, "keys"):
            return {k: row[k] for k in row.keys()}
        if isinstance(row, dict):
            return dict(row)
    except Exception:
        pass
    return {}


def _v454_match_id(match, fallback):
    try:
        return match.get("id") or match.get("event_id") or match.get("match_id") or fallback
    except Exception:
        return fallback


def v454_public_sports_home():
    feed = v436_real_feed(force=False) if 'v436_real_feed' in globals() else {}
    buckets = (feed or {}).get('buckets') or {}
    matches = []
    for bucket in ('live', 'today', 'upcoming'):
        for m in buckets.get(bucket) or []:
            if isinstance(m, dict):
                item = dict(m)
                item['id'] = _v454_match_id(item, len(matches)+1)
                if bucket == 'live': item['is_live'] = True
                matches.append(item)
            if len(matches) >= 12:
                break
        if len(matches) >= 12:
            break
    if not matches:
        base = v436_matches(feed, 'all', 12) if 'v436_matches' in globals() else []
        for i, m in enumerate(base, 1):
            if isinstance(m, dict):
                item = dict(m)
            else:
                item = _v454_row_to_dict(m)
            item['id'] = _v454_match_id(item, i)
            matches.append(item)
    picks_raw = v436_pick_rows(4) if 'v436_pick_rows' in globals() else []
    picks = [_v454_row_to_dict(p) for p in picks_raw]
    counts = (feed or {}).get('counts') or {}
    counts = {
        'live': counts.get('live', len(buckets.get('live') or [])),
        'today': counts.get('today', len(buckets.get('today') or matches)),
        'upcoming': counts.get('upcoming', len(buckets.get('upcoming') or [])),
    }
    combi = v436_combi_summary() if 'v436_combi_summary' in globals() else {'selections': [], 'total_odds': 0}
    return render_template('public_sports_home_v454.html', feed=feed, matches=matches[:12], picks=picks[:4], counts=counts, combi=combi, version=V454_VERSION)

