# =================== V455 CLIENT APP ORDER SYSTEM ===================
# Orden total experiencia cliente: una sola app deportiva pública/cliente,
# navegación única, sin botones duplicados visibles, picks con estado vacío claro
# y escudos fallback premium sin N/A ni cajas rotas.
V455_VERSION = "V455_CLIENT_APP_ORDER_SYSTEM"
APP_VERSION = V455_VERSION


def _v455_get(obj, *keys, default=""):
    for k in keys:
        try:
            if isinstance(obj, dict) and obj.get(k) not in (None, "", "N/A"):
                return obj.get(k)
            if hasattr(obj, "keys") and k in obj.keys() and obj[k] not in (None, "", "N/A"):
                return obj[k]
        except Exception:
            pass
    return default


def _v455_clean_team_name(name, fallback="Equipo"):
    name = str(name or "").strip()
    if not name or name.upper() in {"N/A", "NONE", "NULL", "-"}:
        return fallback
    return name.replace("_", " ")[:42]


def _v455_initials(name):
    name = _v455_clean_team_name(name, "SHARK")
    parts = [p for p in name.replace("-", " ").split() if p]
    if not parts:
        return "S"
    if len(parts) == 1:
        return parts[0][:2].upper()
    return (parts[0][0] + parts[-1][0]).upper()


def _v455_logo(match, side="home"):
    keys = ("home_logo", "home_badge", "strHomeTeamBadge", "home_crest") if side == "home" else ("away_logo", "away_badge", "strAwayTeamBadge", "away_crest")
    logo = _v455_get(match, *keys, default="")
    if logo and str(logo).startswith(("http://", "https://", "/static/")):
        return logo
    return ""


def _v455_match_id(match, fallback):
    mid = _v455_get(match, "id", "event_id", "match_id", "fixture_id", "idEvent", default=fallback)
    return str(mid).replace(" ", "-")


def _v455_normalize_match(match, idx=1):
    m = dict(match) if isinstance(match, dict) else (_v454_row_to_dict(match) if '_v454_row_to_dict' in globals() else {})
    home = _v455_clean_team_name(_v455_get(m, "home", "home_team", "team_home", "strHomeTeam", "local", default="Local"), "Local")
    away = _v455_clean_team_name(_v455_get(m, "away", "away_team", "team_away", "strAwayTeam", "visitor", default="Visitante"), "Visitante")
    status = _v455_get(m, "status", "state", "match_status", default="Programado")
    is_live = bool(_v455_get(m, "is_live", "live", default=False)) or str(status).lower() in {"live", "inplay", "en directo"}
    score_home = _v455_get(m, "home_score", "score_home", "intHomeScore", default="")
    score_away = _v455_get(m, "away_score", "score_away", "intAwayScore", default="")
    score = _v455_get(m, "score", default="")
    if not score and score_home != "" and score_away != "":
        score = f"{score_home}-{score_away}"
    return {
        **m,
        "id": _v455_match_id(m, idx),
        "home": home,
        "away": away,
        "home_initials": _v455_initials(home),
        "away_initials": _v455_initials(away),
        "home_logo": _v455_logo(m, "home"),
        "away_logo": _v455_logo(m, "away"),
        "league": _v455_get(m, "league", "competition", "sport_key", "strLeague", default="Competición"),
        "time": _v455_get(m, "commence_time", "kickoff_time", "date", "time", "strTime", default="Hora por confirmar"),
        "status": "LIVE" if is_live else status,
        "is_live": is_live,
        "score": score,
    }


def _v455_feed():
    feed = v436_real_feed(force=False) if 'v436_real_feed' in globals() else {}
    buckets = (feed or {}).get('buckets') or {}
    raw = []
    for bucket in ("live", "today", "upcoming"):
        raw.extend(buckets.get(bucket) or [])
    if not raw and 'v436_matches' in globals():
        try:
            raw = v436_matches(feed, 'all', 24) or []
        except Exception:
            raw = []
    matches = []
    seen = set()
    for i, item in enumerate(raw, 1):
        m = _v455_normalize_match(item, i)
        key = (m.get('home','').lower(), m.get('away','').lower(), str(m.get('time',''))[:16])
        if key in seen:
            continue
        seen.add(key)
        matches.append(m)
    live = [m for m in matches if m.get('is_live')]
    today = matches[:16]
    upcoming = matches[8:24] if len(matches) > 8 else matches[:8]
    counts = (feed or {}).get('counts') or {}
    return {
        "feed": feed,
        "matches": matches[:24],
        "live": live[:10],
        "today": today[:16],
        "upcoming": upcoming[:12],
        "counts": {"live": counts.get('live', len(live)), "today": counts.get('today', len(today)), "upcoming": counts.get('upcoming', len(upcoming))},
    }


def _v455_picks(limit=12):
    raw = []
    if 'v436_pick_rows' in globals():
        try:
            raw = v436_pick_rows(limit) or []
        except Exception:
            raw = []
    picks = []
    for i, p in enumerate(raw, 1):
        d = dict(p) if isinstance(p, dict) else (_v454_row_to_dict(p) if '_v454_row_to_dict' in globals() else {})
        title = _v455_get(d, 'title', 'match', 'fixture', default='Pick SHARK')
        picks.append({
            **d,
            'id': _v455_get(d, 'id', 'pick_id', default=i),
            'title': title,
            'pick': _v455_get(d, 'pick', 'selection', 'market', default='Ver selección'),
            'odds': _v455_get(d, 'odds', 'cuota', default='—'),
            'stake': _v455_get(d, 'stake', default='1u'),
            'risk': _v455_get(d, 'risk', 'riesgo', default='Medio'),
            'score': _v455_get(d, 'score', 'confidence', default='72'),
            'reason': _v455_get(d, 'reason', 'analysis', 'content', default='Señal preparada por SHARK. Entra para ver contexto, riesgo y gestión de banca.'),
        })
    return picks[:limit]


def _v455_context(active="inicio"):
    data = _v455_feed()
    picks = _v455_picks(12)
