def v488_combi_api():
    modo = request.args.get("modo", "equilibrada")
    partidos = int(request.args.get("partidos", "3") or 3)
    return {"ok": True, "modo": modo, "partidos": partidos, "legs": _v488_build_legs(partidos, modo)}

